@@ -0,0 +1,9 @@
+// Sites: each location belongs to a site.
+import { AppError } from "../errors.js";
+
+/** Location ids belonging to `site` (all locations when `site` is omitted). */
+export function siteLocations(store, site) {
+  if (site === undefined) return new Set((store.data.locations ?? []).map((l) => l.id));
+  if (!(store.data.sites ?? []).some((s) => s.id === site)) throw new AppError("unknown_site", { id: site });
+  return new Set((store.data.locations ?? []).filter((l) => l.site === site).map((l) => l.id));
+}
